// =================================================================================================//	CTagBGM.h//		DNML for Macintosh ＢＧＭタグ処理クラス定義（試験運用）////	Copyright 2001, A.Iisaka// =================================================================================================#ifndef	_H_CTagBGM#define	_H_CTagBGM#include <stdio.h>#include <stdlib.h>#include <iostream>#include "CTagBasic.h"// -------------------------------------------------------------------------------------------------//	･ CTagBGM class// -------------------------------------------------------------------------------------------------class	CTagBGM			:	public CTagBasic	{	int				mBgmTimeout;public:					CTagBGM(dnmlparse		**inDNML,							cardparse		**inCARD,							CAlias			**inAlias,							CGraphics		**inGraphics,							CSound			**inSound)							:	CTagBasic(inDNML, inCARD, inAlias, inGraphics, inSound)						{							mBgmTimeout = 5000;						};					~CTagBGM()						{};	Boolean			run(TagBasic *inTag)						{							TagBgm			*tag = (TagBgm *)inTag;							if (!mInProgress && mActive) {								char			*src = nil, *folder = nil, bgmName[256];								int				loopCount;								Boolean			cdFlag = false;																			if (tag->k_src) {									if ((src = (*mAlias)->getItem(CSTR(tag->k_src))) == nil) {										src = CSTR(tag->k_src);									}									if (tag->k_folder) {										if (stricmp(CSTR(tag->k_folder), "CURRENT")) {											if ((folder = (*mAlias)->getItem(CSTR(tag->k_folder))) == nil) {												folder = CSTR(tag->k_folder);											}										}									}									loopCount = (tag->k_loop) ? atoi(CSTR(tag->k_loop)) : -1;									if (!folder) {										if (strstr(src, ".CDA") == NULL && strstr(src, ".cda") == NULL) {											sprintf(bgmName, "%s%s", (*mDNML)->currentFolder, src);										} else {											cdFlag = true;											strcpy(bgmName, src);										}									} else {										if (strstr(src, ".CDA") != NULL || strstr(src, ".cda") != NULL) {											cdFlag = true;											strcpy(bgmName, src);										} else {											if (folder[strlen(folder)-1] != '/') {												sprintf(bgmName, "%s/%s", folder, src);											} else {												sprintf(bgmName, "%s%s", folder, src);											}										}									}									if (!cdFlag) {										(*mDNML)->convertNative(bgmName);									}									(*mSound)->BGM_Stop();									(*mSound)->BGM_Play(bgmName, loopCount, -1);									(*mCARD)->setBuffer("(BGM_PLAY=1)");									(*mCARD)->yyparse();									mInProgress = true;									(*mGraphics)->ResetTimer();								} else {									(*mSound)->BGM_Stop();								}							} else {								if ((*mSound)->BGM_CheckPlay()) {									mInProgress = false;								}								if (mInProgress) {									if ((*mGraphics)->GetTimer() > mBgmTimeout) {										mActive     = false;										mInProgress = false;									}								}							}							return mInProgress;						};	Boolean			stop(TagBasic *inTag)						{							if (!inTag) {								(*mSound)->BGM_Stop();								mInProgress = false;							} else {								if (!mInProgress && mActive) {									TagEBgm			*tag = (TagEBgm*)inTag;									Boolean			waitFlag;									int				fadeOut;																		fadeOut = (tag->k_time) ? atoi(CSTR(tag->k_time)) : 0;									if (tag->k_mode) {										if (!stricmp(CSTR(tag->k_mode), "PASS")) {											waitFlag = false;										} else {											waitFlag = (fadeOut) ? true : false;										}									} else {										waitFlag = true;									}									if (!fadeOut) {										(*mSound)->BGM_Stop();									} else {										(*mSound)->BGM_FadeOut(fadeOut);										if (waitFlag) {											mInProgress = true;										}									}								} else {									if (!(*mSound)->BGM_CheckPlay()) {										mInProgress = false;									}									if (!mInProgress) {										if ((*mGraphics)->GetTimer() > mBgmTimeout) {											mInProgress = false;										}									}								}							}							return mInProgress;						};	void			idle(void)						{							if (mActive) {								if ((*mSound)->BGM_CheckPlay() == 0) {									(*mCARD)->setBuffer("(BGM_PLAY=0)");									(*mCARD)->yyparse();								}							}						};	int				getVolume()						{							return (*mSound)->BGM_GetVolume();						};	void			setVolume(int inVol)						{							(*mSound)->BGM_SetVolume(inVol);						};};#endif	// _H_CTagBGM